@pytest.mark.parametrize(
    "mode,expected", STYLE_VALUES_CASES.values(), ids=STYLE_VALUES_CASES
)
def test_style_values(mode, expected, monkeypatch):
    finding = {"severity": "medium", "title": "T", "body": "b"}
    style = None
    if mode == "registry":
        monkeypatch.setattr(registry, "SEVERITY_EMOJI", {"medium": "sentinel"})
    else:
        style = compose.CommentStyle(
            "MARK *Brand*",
            {"severity": "{emoji}"},
            "fallback",
            {"documented_rule": "{rule_source_label}"},
            "{fallback-rule}",
        )
        if mode == "generator":
            finding.update(
                severity="severity",
                claude_md_rule="Rule",
                rule_source="documented_rule",
            )
    assert compose.render_comment_body(finding, style=style) == expected


