@pytest.mark.parametrize(
    "sections,marker,platform,surface,limit,expected_body,expected_folded",
    INLINE_ENVELOPES_CASES.values(),
    ids=INLINE_ENVELOPES_CASES,
)
def test_inline_envelopes(
    sections, marker, platform, surface, limit, expected_body, expected_folded
):
    with patch.dict(
        PLATFORM_BODY_LIMITS[platform]["surfaces"][surface], {"bytes": limit}
    ):
        assert compose.compose_inline_body(
            sections, platform=platform, surface=surface, marker_suffix=marker
        ) == compose.InlineBody(expected_body, expected_folded)


def test_summary_envelopes() -> None:
    groups = [skipped_group("src/app.py", 9, title="Skipped", body="b")]
    composed = compose.compose_review_body(
        "x" * 64889,
        groups,
        platform="github",
        findings_count=1,
        sha=SHA,
        inline_count=0,
    )
    assert (
        composed.shown,
        composed.omitted,
        composed.folded_bytes,
        composed.omitted_entries,
    ) == (1, 0, 0, ())
    assert len(composed.body.encode("utf-8")) == 65536
    assert "following 1 finding references" in composed.body
    assert "#### `src/app.py:9`\n\n**\U0001f7e0 [HIGH] Skipped**\n\nb" in composed.body
    assert composed.body.startswith(SUMMARY_HEADER + "\n\n" + "x" * 64889)
    assert composed.body.endswith(
        FOOTER.replace('"findings_count":0', '"findings_count":1')
    )


